/**
 * Vagabond — Refresh World Data
 * ---------------------------------------------------------------------------
 * Forces every Actor, Item and canvas Token to re-run data preparation and
 * re-render, WITHOUT a full page reload.
 *
 * Use it after you change system code that only affects:
 *   - data preparation / derived data (prepareBaseData, prepareDerivedData)
 *   - helper logic used during preparation
 *   - CONFIG.VAGABOND / homebrew config values already loaded in memory
 *
 * A full page reload (F5) is still required for:
 *   - DataModel SCHEMA changes (new/removed fields, changed field types)
 *   - migrateData changes
 *   - init / ready hook logic, template (.hbs) structure, new CONFIG wiring
 * because Foundry does not hot-reload .mjs modules.
 * ---------------------------------------------------------------------------
 */
(async () => {
  if (!game.user.isGM) return ui.notifications.warn("Refresh World Data: GM only.");

  const stats = { actors: 0, items: 0, synthetic: 0, apps: 0, errors: 0 };

  const reprep = (doc, label) => {
    try {
      doc.reset?.();       // restore _source + re-init DataModel
      doc.prepareData();   // belt-and-braces for classes without a useful reset()
      return true;
    } catch (err) {
      stats.errors++;
      console.error(`Refresh World Data | ${label} ${doc?.uuid ?? doc?.id ?? "?"} failed`, err);
      return false;
    }
  };

  // 1. World actors (embedded items are prepared inside prepareData)
  for (const actor of game.actors) {
    if (reprep(actor, "Actor")) stats.actors++;
    for (const item of actor.items) reprep(item, "Item(embedded)");
  }

  // 2. World items
  for (const item of game.items) if (reprep(item, "Item")) stats.items++;

  // 3. Synthetic (unlinked) token actors on the active scene
  for (const token of canvas?.tokens?.placeables ?? []) {
    if (token.actor && !token.document.actorLink) {
      if (reprep(token.actor, "Actor(synthetic)")) stats.synthetic++;
      for (const item of token.actor.items) reprep(item, "Item(synthetic)");
    }
  }

  // 4. Re-render every open application (V1 windows + V2 instances)
  const seen = new Set();
  const renderApp = (app) => {
    if (!app || seen.has(app)) return;
    seen.add(app);
    try { app.render(false); stats.apps++; } catch (err) { stats.errors++; }
  };
  for (const app of Object.values(ui.windows ?? {})) renderApp(app);
  for (const app of foundry.applications?.instances?.values?.() ?? []) renderApp(app);

  // 5. Redraw token visuals (bars, effects, nameplate)
  for (const token of canvas?.tokens?.placeables ?? []) {
    try { token.renderFlags.set({ redraw: true }); } catch (_) {}
  }

  // 6. Sidebar directories
  for (const key of ["actors", "items", "combat", "effects", "compendium"]) {
    try { ui[key]?.render(false); } catch (_) {}
  }

  ui.notifications.info(
    `Refresh World Data — ${stats.actors} actors, ${stats.items} items, ` +
    `${stats.synthetic} token actors, ${stats.apps} apps re-rendered` +
    (stats.errors ? ` (${stats.errors} errors, see console)` : "") + "."
  );
  console.log("Refresh World Data | done", stats);
})();
